      <span class="pv" aria-hidden="true">${$==="system"?'<span class="d"><i></i><i></i><i></i></span><span class="l"><i></i><i></i><i></i></span>':`<span class="${$==="dark"?"d":"l"}"><i></i><i></i><i></i></span>`}</span>
